#include <cuda_runtime.h>
#include <vector>
#include <fstream>
#include <chrono>
#include <cmath>
#include <string>
#include "dcn_v2_im2col_cuda.cu"
#include "study_params.h"
#define C(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDAfailure%s line%d\n",cudaGetErrorString(e),__LINE__);exit(1);}}while(0)
std::vector<float> read_float(const std::string&name,int n){std::ifstream f(name,std::ios::binary);std::vector<float>a(n);f.read((char*)a.data(),n*4);if(f.gcount()!=n*4)exit(2);return a;}
struct Buffer{float *base,*ptr;std::vector<float> initial;Buffer(std::vector<float>x){initial.assign(16,777);initial.insert(initial.end(),x.begin(),x.end());initial.insert(initial.end(),16,777);C(cudaMalloc(&base,initial.size()*4));ptr=base+16;reset();}void reset(){C(cudaMemcpy(base,initial.data(),initial.size()*4,cudaMemcpyHostToDevice));}void append(std::vector<double>&a){std::vector<float>x(initial.size());C(cudaMemcpy(x.data(),base,x.size()*4,cudaMemcpyDeviceToHost));for(float v:x)a.push_back(v);}~Buffer(){cudaFree(base);}};
struct Work{Spec s;Buffer image,offset,mask,columns,gi,go,gm;Work(Spec t):s(t),image(read_float("case"+std::to_string(t.id)+"_image_f32.bin",t.C*t.H*t.W)),offset(read_float("case"+std::to_string(t.id)+"_offset_f32.bin",t.G*2*t.KH*t.KW*t.OH*t.OW)),mask(read_float("case"+std::to_string(t.id)+"_mask_f32.bin",t.G*t.KH*t.KW*t.OH*t.OW)),columns(read_float("case"+std::to_string(t.id)+"_colgrad_f32.bin",t.C*t.KH*t.KW*t.OH*t.OW)),gi(std::vector<float>(t.C*t.H*t.W,0)),go(std::vector<float>(t.G*2*t.KH*t.KW*t.OH*t.OW,0)),gm(std::vector<float>(t.G*t.KH*t.KW*t.OH*t.OW,0)){}void reset(){image.reset();offset.reset();mask.reset();columns.reset();gi.reset();go.reset();gm.reset();}void prefix(std::vector<double>&a){a.insert(a.end(),{double(s.id),double(s.sample),double(s.C),double(s.G),double(s.H),double(s.W),double(s.KH),double(s.KW),double(s.PH),double(s.PW),double(s.SH),double(s.SW),double(s.DH),double(s.DW),double(s.OH),double(s.OW)});image.append(a);offset.append(a);mask.append(a);columns.append(a);gi.append(a);go.append(a);gm.append(a);}void pipeline(){modulated_deformable_col2im_coord_cuda(0,columns.ptr,image.ptr,offset.ptr,mask.ptr,1,s.C,s.H,s.W,s.OH,s.OW,s.KH,s.KW,s.PH,s.PW,s.SH,s.SW,s.DH,s.DW,s.G,go.ptr,gm.ptr);C(cudaGetLastError());modulated_deformable_col2im_cuda(0,columns.ptr,offset.ptr,mask.ptr,1,s.C,s.H,s.W,s.OH,s.OW,s.KH,s.KW,s.PH,s.PW,s.SH,s.SW,s.DH,s.DW,s.G,gi.ptr);C(cudaGetLastError());modulated_deformable_im2col_cuda(0,image.ptr,offset.ptr,mask.ptr,1,s.C,s.H,s.W,s.OH,s.OW,s.KH,s.KW,s.PH,s.PW,s.SH,s.SW,s.DH,s.DW,s.G,columns.ptr);C(cudaGetLastError());}void tail(std::vector<double>&a){columns.append(a);gi.append(a);go.append(a);gm.append(a);}};
int main(int argc,char**argv){std::ifstream f(argv[1],std::ios::binary);std::vector<double>expected(COUNT);f.read((char*)expected.data(),COUNT*8);if(f.gcount()!=COUNT*8)return 2;std::vector<Work*>works;for(auto&s:SPECS)works.push_back(new Work(s));for(auto w:works){w->pipeline();C(cudaDeviceSynchronize());}for(int trial=1;trial<=5;trial++){for(auto w:works)w->reset();std::vector<double>out;for(auto w:works)w->prefix(out);if(out.size()!=PREFIX)return 3;double seconds=0;for(auto w:works){C(cudaDeviceSynchronize());auto begin=std::chrono::steady_clock::now();w->pipeline();C(cudaDeviceSynchronize());seconds+=std::chrono::duration<double>(std::chrono::steady_clock::now()-begin).count();}for(auto w:works)w->tail(out);bool good=out.size()==COUNT;double error=0;for(int i=0;i<COUNT;i++){double e=std::abs(out[i]-expected[i]);double budget=i<PREFIX?0:2e-6+2e-6*std::abs(expected[i]);good=good&&std::isfinite(out[i])&&e<=budget;error=std::max(error,e);}int off=PREFIX;for(auto&s:SPECS)for(int n: {s.C*s.KH*s.KW*s.OH*s.OW,s.C*s.H*s.W,s.G*2*s.KH*s.KW*s.OH*s.OW,s.G*s.KH*s.KW*s.OH*s.OW}){for(int j=0;j<16;j++)good=good&&out[off+j]==777&&out[off+n+16+j]==777;off+=n+32;}std::string path=std::string(getenv("STUDY_OUTPUT_DIR"))+"/convolutionDeformable_trial"+std::to_string(trial)+".bin";std::ofstream save(path,std::ios::binary);save.write((char*)out.data(),out.size()*8);save.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.17g,\"max_rel_error\":null,\"jit_excluded\":true,\"timing_region\":\"sum4batch_backward_coord_col2im_im2col_customkernel_triplets_completion\",\"internal_repeats\":1,\"iterations\":1,\"kernel_launches\":12,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,good?"true":"false",out.size(),error,path.c_str(),out.size());fflush(stdout);if(!good)return 4;}for(auto w:works)delete w;return 0;}
